import{z as c,x as E,o as s,c as d,q as n,j as i,D as e,d as o,s as p,S as l,b as r}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"容器的 OS 含义","description":"","frontmatter":{"title":"容器的 OS 含义","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/container-os.md","filePath":"cs/container-os.md","lastUpdated":1791413859000}'),A={name:"cs/container-os.md"};function B(m,a,u,h,f,_){const t=E("Mermaid");return s(),d("div",null,[a[2]||(a[2]=n('<h1 id="容器的-os-含义" tabindex="-1">容器的 OS 含义 <a class="header-anchor" href="#容器的-os-含义" aria-label="Permalink to &quot;容器的 OS 含义&quot;">​</a></h1><div class="epigraph"><p>容器不是第二台内核：它是命名空间中的视图、cgroup 中的配额，加上一个用户空间根文件系统。</p><footer>—— 据 Linux 容器相关文档；Tanenbaum 对虚拟化与容器对照的整理</footer></div><p><a href="/cs/cgroups">上一课</a>给了配额，<a href="/cs/namespaces">namespaces</a> 给了视图。<a href="/cs/init-userspace">init</a> 可以在 pid 空间里再跑一个 1 号。<a href="/cs/vfs">VFS</a> 的绑定挂载把主机目录接到容器根。缺口是<strong>收束定义</strong>：工程上的「容器」= 这些 OS 原语的打包，对比下一课才开始的真虚拟机（客内核）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若把容器说成轻量虚拟机，会误以为有独立页表根与独立中断。实际上：同一 <a href="/cs/user-kernel-split">用户/内核分裂</a>，同一系统调用表，除非再加过滤。隔离强度弱于 VM：内核漏洞是共享的。收益是启动快、密度高、不模拟设备。缺口：讲清打包（镜像只是 rootfs + 元数据），运行时负责 clone 标志、cgroup 路径、网卡进 net ns。本课不写编排器。</p><p><span class="marginnote">seccomp、capabilities、只读挂载是常见加固，下一课专讲系统调用过滤。本课不给逃逸清单。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>运行时：<code>clone</code> 新 ns、配 cgroup、pivot_root 到镜像、exec 入口。网络：veth 一对进 net ns，外层接网桥——链路层细节留给网络课，这里只承认「另一份网络栈视图」。存储：overlay 等联合挂载是 VFS 功能，不是新内核。</p><p><span class="marginnote">pivot_root 就是给新进程换根目录：把容器镜像所在的目录变成它的 /，此后它看到的文件系统只从镜像里长出来。像给舞台换布景——台上的演员（进程）以为置身另一个世界，幕布外还是同一个机房。</span></p>',9)),(s(),i(l,null,{default:e(()=>[p(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20IMG%5B%22rootfs%20%E9%95%9C%E5%83%8F%22%5D%20--%3E%20NS%5B%22namespaces%20%E8%A7%86%E5%9B%BE%22%5D%0A%20%20NS%20--%3E%20CG%5B%22cgroup%20%E9%85%8D%E9%A2%9D%22%5D%0A%20%20CG%20--%3E%20EXEC%5B%22exec%20%E5%85%A5%E5%8F%A3%E8%BF%9B%E7%A8%8B%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[o("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"容器把本 OS 课从进程到挂载的对象组合起来，而不引入客机页表。它解释了为何「容器里 cat /proc/cpuinfo」仍是主机 CPU：没有 trap-and-emulate。下一课缩小系统调用面；再下一课才是真正的敏感指令陷入。",-1)),(s(),i(l,null,{default:e(()=>[p(t,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20CP%5B%22%E5%AE%B9%E5%99%A8%E5%86%85%E8%BF%9B%E7%A8%8B%22%5D%20--%3E%20SC%5B%22%E5%90%8C%E4%B8%80%E6%9D%A1%E7%B3%BB%E7%BB%9F%E8%B0%83%E7%94%A8%E8%B7%AF%E5%BE%84%22%5D%0A%20%20SC%20--%3E%20HK%5B%22%E5%AE%BF%E5%86%85%E6%A0%B8%E7%9B%B4%E6%8E%A5%E6%89%A7%E8%A1%8C%22%5D%0A%20%20VP%5B%22VM%20%E5%86%85%E8%BF%9B%E7%A8%8B%22%5D%20--%3E%20GK%5B%22%E5%85%88%E9%97%AE%E5%AE%A2%E6%9C%BA%E5%86%85%E6%A0%B8%22%5D%0A%20%20GK%20--%3E%20TRAP%5B%22%E9%99%B7%E5%85%A5%20hypervisor%20%E6%A8%A1%E6%8B%9F%E8%AE%BE%E5%A4%87%22%5D%0A%20%20TRAP%20--%3E%20HK%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=n('<p><span class="marginnote">数字实例：容器启动常以毫秒计——clone 几个命名空间、挂一个 rootfs 就完事；VM 要先跑一遍固件加内核引导，通常以秒计。密度同理：一台 64 GB 的宿主机能塞几十上百个容器，同规格 VM 每台光内核内存就要吃掉几百 MB。</span></p><p>与过度提交、页 Cache 共用主机内存：cgroup 只是上限。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 gVisor 等用户态内核。不把 OCI 规范当必背。下一课：即便 ns 切了，系统调用号仍通到同一内核——用过滤器裁面。</p><p>后课默认：容器共享内核。按系统调用号拦截，下一课 seccomp。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>容器 = namespaces + cgroups + 用户态 rootfs，共享内核。</li><li>不是客机，没有独立特权 ISA 视图。</li><li>系统调用过滤是 seccomp 的缺口。</li><li>出处：Linux namespaces/cgroup 文档；Tanenbaum <em>MOS</em>。</li></ul><p><span class="marginnote">常见误区：「容器更轻，所以是功能少的迷你系统」。其实容器里跑的是普通 Linux 程序，ps、cat、python 照常工作；少的不是功能，是那份独立内核——视图、配额、根目录各发一份，系统调用最后仍回到同一张表。</span></p>',8))])}const T=c(A,[["render",B]]);export{g as __pageData,T as default};
